package edu.ankara.audiometer.infrastructure.serial;
import com.fazecast.jSerialComm.SerialPort;import edu.ankara.audiometer.domain.fp.Result;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
public final class JSerialCommGateway implements SerialPortGateway { private SerialPort port; private ExecutorService executor; private volatile boolean running; private SerialConnectionStatus status=SerialConnectionStatus.disconnected(); public List<String> listPorts(){return Arrays.stream(SerialPort.getCommPorts()).map(SerialPort::getSystemPortName).toList();}
 public Result<SerialConnectionStatus,String> connect(String portName,int baudRate,Consumer<String> onLine){ try{ port=SerialPort.getCommPort(portName); port.setComPortParameters(baudRate,8,SerialPort.ONE_STOP_BIT,SerialPort.NO_PARITY); port.setComPortTimeouts(SerialPort.TIMEOUT_READ_BLOCKING,250,0); if(!port.openPort()) return Result.err("Cannot open "+portName); running=true; executor=Executors.newSingleThreadExecutor(r->new Thread(r,"serial-reader")); executor.submit(()->readLoop(onLine)); status=new SerialConnectionStatus(true,portName,"Connected"); return Result.ok(status);}catch(Exception e){return Result.err(e.getMessage());}}
 private void readLoop(Consumer<String> onLine){ try(var br=new BufferedReader(new InputStreamReader(port.getInputStream(),StandardCharsets.UTF_8))){ String line; while(running && (line=br.readLine())!=null) onLine.accept(line);}catch(IOException ignored){ if(running) status=new SerialConnectionStatus(false,status.portName(),"Read error"); }}
 public Result<Void,String> disconnect(){ running=false; if(executor!=null) executor.shutdownNow(); if(port!=null) port.closePort(); status=SerialConnectionStatus.disconnected(); return Result.ok(null);} public Result<Void,String> send(String command){ if(port==null||!port.isOpen()) return Result.err("Serial port not connected"); try{ port.getOutputStream().write((command+"\n").getBytes(StandardCharsets.UTF_8)); port.getOutputStream().flush(); return Result.ok(null);}catch(IOException e){return Result.err(e.getMessage());}} public SerialConnectionStatus status(){return status;} }
